text:
5 一个简单例子
论文开篇用两个数字说明了要点：两个拟合均值分别为每月 1.0% 和 0.7%，因子部分同为 0.6%，于是 alpha 分别为 0.4% 和 0.1%；后者更小，只是因为它的均值更低（第 1 节，示例）。下面的示例用五只股票和一个因子做同样的事。

palette = ({
  naipca_iab: "#18557f", complete: "#18557f",
  qz_ipca: "#8a6a1a",
  ipca: "#6f9cc0", rp_pca: "#7a7a7a", ff5: "#b3b3b3",
  naipca_beta_only: "#8a8378", beta_only: "#8a8378",
  band: "rgba(0,0,0,0.06)", muted: "rgba(0,0,0,0.6)", rule: "rgba(0,0,0,0.1)"
})
LANG = (document.documentElement.lang || "en").startsWith("zh") ? "zh" : "en"
STR = ({ en: { view: "View", cost: "Cost (bp per traded dollar)", universe: "Universe", sample: "Sample (months)", log: "Log scale", models: "Models", statistic: "Statistic", theme: "Theme", sort: "Sort by", method: "Method", scenario: "Scenario", block: "Block (months)", metric: "Metric", intervals: "Intervals", cost_bp: "One-way cost (bp)", failed: "Interactive data failed to load. The static figure is shown instead." },
        zh: { view: "视图", cost: "成本（每交易一美元，基点）", universe: "股票池", sample: "样本（月）", log: "对数坐标", models: "模型", statistic: "统计量", theme: "主题", sort: "排序", method: "方法", scenario: "情景", block: "块长（月）", metric: "指标", intervals: "区间", cost_bp: "单边成本（基点）", failed: "交互数据加载失败，改为显示静态图。" } })
t = (k) =&gt; STR[LANG][k] ?? STR.en[k] ?? k
fmt2 = (x) =&gt; (x == null || Number.isNaN(x)) ? "n/a" : x.toFixed(2)
fmt1 = (x) =&gt; (x == null || Number.isNaN(x)) ? "n/a" : x.toFixed(1)
fmtBp = (x) =&gt; (x == null || Number.isNaN(x)) ? "&gt; 500" : `${Math.round(x)} bp`
parseMonth = (s) =&gt; new Date(`${s}-01T00:00:00Z`)
// Sharpe, annualised, sample std (ddof = 1): matches the release convention
sharpe = (r) =&gt; {
  const n = r.length, m = r.reduce((a, b) =&gt; a + b, 0) / n
  const v = r.reduce((a, b) =&gt; a + (b - m) ** 2, 0) / (n - 1)
  const vol = Math.sqrt(v) * Math.sqrt(12)
  return vol &gt; 1e-12 ? (m * 12) / vol : NaN
}
netSeries = (r, to, bp) =&gt; r.map((x, i) =&gt; x - to[i] * bp / 1e4)
wealthPath = (r) =&gt; { let w = 1; return r.map((x) =&gt; (w *= 1 + x)) }
nberMarks = (nber) =&gt; Plot.rectX(nber, { x1: (d) =&gt; parseMonth(d.start), x2: (d) =&gt; parseMonth(d.end), fill: palette.band })























































































图 1：两个模型，两个 alpha。示意性示例（虚构数字，并非论文估计值）。 五只股票的虚构数字；表格把每个拟合均值与每个载荷空间交叉组合。


viewof pe_toy_keep = Inputs.range([0, 1], { value: 0.5, step: 0.05, label: LANG === "zh" ? "均值：B 保留 A 额外信号的比例" : "Mean: share of A's extra signal B keeps" })







viewof pe_toy_tilt = Inputs.range([0, 1], { value: 0, step: 0.05, label: LANG === "zh" ? "空间：B 的因子吸收 A 额外信号的程度" : "Space: how much B's factor absorbs A's extra signal" })







pe_toy_stocks = ["Stock 1", "Stock 2", "Stock 3", "Stock 4", "Stock 5"]
pe_toy_betaA = [0.6, 0.9, 1.0, 1.2, 1.5]
pe_toy_premium = 0.5
pe_toy_extra = [0.40, -0.20, 0.10, -0.30, 0.25]
// At Space = 1, B's exposures tilt fully toward A's extra signal, so one factor spans A's mean
pe_toy_shift = pe_toy_extra.map((e) =&gt; 2 * e)
pe_toy_betaB = pe_toy_betaA.map((b, i) =&gt; b + pe_toy_tilt * pe_toy_shift[i])
pe_toy_meanA = pe_toy_betaA.map((b, i) =&gt; b * pe_toy_premium + pe_toy_extra[i])
pe_toy_meanB = pe_toy_betaA.map((b, i) =&gt; b * pe_toy_premium + pe_toy_keep * pe_toy_extra[i])
// Equal-stock projection of a mean onto the span of one exposure vector
pe_toy_split = (beta, mean) =&gt; {
  const bb = beta.reduce((s, b) =&gt; s + b * b, 0), bm = beta.reduce((s, b, i) =&gt; s + b * mean[i], 0)
  const factor = beta.map((b) =&gt; b * bm / bb)
  return { factor, intercept: mean.map((m, i) =&gt; m - factor[i]) }
}
pe_toy_rms = (r) =&gt; 100 * Math.sqrt(r.reduce((s, x) =&gt; s + x * x, 0) / r.length)   // percent -&gt; basis points
pe_toy_cell = (beta, mean) =&gt; pe_toy_rms(pe_toy_split(beta, mean).intercept)
pe_toy_AA = pe_toy_cell(pe_toy_betaA, pe_toy_meanA)
pe_toy_BB = pe_toy_cell(pe_toy_betaB, pe_toy_meanB)
pe_toy_BA = pe_toy_cell(pe_toy_betaB, pe_toy_meanA)
pe_toy_AB = pe_toy_cell(pe_toy_betaA, pe_toy_meanB)
pe_toy_mA = LANG === "zh" ? "模型 A" : "Model A"
pe_toy_mB = LANG === "zh" ? "模型 B" : "Model B"
pe_toy_pF = LANG === "zh" ? "因子部分" : "Factor part"
pe_toy_pI = LANG === "zh" ? "特征截距部分" : "Characteristic-intercept part"
pe_toy_rows = [[pe_toy_mA, pe_toy_betaA, pe_toy_meanA], [pe_toy_mB, pe_toy_betaB, pe_toy_meanB]].flatMap(([m, beta, mean]) =&gt; {
  const s = pe_toy_split(beta, mean)
  return pe_toy_stocks.flatMap((st, i) =&gt; [
    { model: m, stock: st, part: pe_toy_pF, value: s.factor[i] },
    { model: m, stock: st, part: pe_toy_pI, value: s.intercept[i] }
  ])
})
pe_toy_totals = [[pe_toy_mA, pe_toy_meanA], [pe_toy_mB, pe_toy_meanB]].flatMap(([m, mean]) =&gt; pe_toy_stocks.map((st, i) =&gt; ({ model: m, stock: st, value: mean[i] })))





















































































































































pe_toy_chart = Plot.plot({
  width: Math.min(width, 760), height: 280, marginLeft: 50, marginTop: 36, marginBottom: 40, style: { fontFamily: "inherit", fontSize: 12 },
  ariaLabel: "Illustrative example: fitted expected returns split into a factor part and a characteristic-intercept part",
  ariaDescription: "Stacked bars for five illustrative stocks under two models. Dots mark each stock's total fitted mean.",
  fx: { label: null },
  x: { label: LANG === "zh" ? "股票" : "Stock", tickFormat: (d) =&gt; d.replace("Stock ", ""), axis: "bottom" },
  y: { label: LANG === "zh" ? "拟合均值（每月 %）" : "Fitted mean (% per month)", grid: true },
  color: { domain: [pe_toy_pF, pe_toy_pI], range: [palette.complete, palette.qz_ipca], legend: true },
  marks: [
    Plot.ruleY([0], { stroke: palette.muted }),
    Plot.barY(pe_toy_rows, { fx: "model", x: "stock", y: "value", fill: "part", title: (d) =&gt; `${d.model}, ${d.stock}\n${d.part}: ${d.value.toFixed(2)}%` }),
    Plot.dot(pe_toy_totals, { fx: "model", x: "stock", y: "value", fill: "white", stroke: "black", r: 3.5, title: (d) =&gt; `${LANG === "zh" ? "拟合均值合计" : "Total fitted mean"}: ${d.value.toFixed(2)}%` })
  ]
})







pe_toy_table = {
  const zh = LANG === "zh"
  const c = (x, diag) =&gt; `&lt;td style="text-align:right;${diag ? "font-weight:600" : ""}"&gt;${fmt1(x)} bp&lt;/td&gt;`
  return html`&lt;table class="table table-sm" style="max-width:520px"&gt;
  &lt;thead&gt;&lt;tr&gt;&lt;th&gt;${zh ? "载荷空间 ↓ / 拟合均值 →" : "Loading space ↓ / fitted mean →"}&lt;/th&gt;&lt;th style="text-align:right"&gt;${zh ? "模型 A 的均值" : "Model A's mean"}&lt;/th&gt;&lt;th style="text-align:right"&gt;${zh ? "模型 B 的均值" : "Model B's mean"}&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
  &lt;tbody&gt;&lt;tr&gt;&lt;td&gt;${zh ? "模型 A 的空间" : "Model A's space"}&lt;/td&gt;${c(pe_toy_AA, true)}${c(pe_toy_AB, false)}&lt;/tr&gt;
  &lt;tr&gt;&lt;td&gt;${zh ? "模型 B 的空间" : "Model B's space"}&lt;/td&gt;${c(pe_toy_BA, false)}${c(pe_toy_BB, true)}&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;
  &lt;p class="figcaption" style="margin-top:.3rem"&gt;${zh
    ? `各自的“alpha”：A 为 ${fmt1(pe_toy_AA)} bp，B 为 ${fmt1(pe_toy_BB)} bp。只换空间（均值固定为 A）：${fmt1(pe_toy_AA)} → ${fmt1(pe_toy_BA)} bp；只换均值（空间固定为 A）：${fmt1(pe_toy_AA)} → ${fmt1(pe_toy_AB)} bp。`
    : `Own "alpha": ${fmt1(pe_toy_AA)} bp for A, ${fmt1(pe_toy_BB)} bp for B. Change only the space (A's mean held fixed): ${fmt1(pe_toy_AA)} → ${fmt1(pe_toy_BA)} bp. Change only the mean (A's space held fixed): ${fmt1(pe_toy_AA)} → ${fmt1(pe_toy_AB)} bp.`}&lt;/p&gt;`
}







读图说明。每根柱子是一只股票的拟合均值，拆成因子部分（蓝色）和特征截距部分（金色），圆点为总值。表格给出每个均值相对每个空间的截距部分均方根，单位为每月基点；对角线是各模型自己的 alpha。来源：为本页设计的示例数字，并非论文估计值；版式参照论文表 1。


“均值”滑块决定模型 B 的拟合均值保留多少模型 A 的额外（非因子）信号；“空间”滑块让模型 B 的因子吸收这部分信号。默认设置下，B 的 alpha（13.4 bp）是 A（26.7 bp）的一半。沿第一行看：把 B 的均值放进 A 的空间，降幅相同；沿第一列看：B 的空间并未减少 A 的残差。所以变的是均值。再把两个滑块都推到 1：B 的 alpha 降为零，但这次是第一列下降、第一行不变，即 B 的因子解释得更多。两种情形的对角线看起来差不多，只有交叉组合能把它们区分开。

5 一个简单例子
设有两个特征 A 与 B，比如两种价值指标，截面相关系数为 ρ。在普通尺子下，二者的系数向量相互垂直，欧氏模型因而可以把 A 放进潜在因子模块、把 B 放进基准因子模块；在特征尺子下，二者的重叠为 ρ。设被定价方向在 A、B 上的载荷相同。把滑块向 0 拖动，两把尺子趋于一致；向上拖动，两个“互不相干”的模块合计声称解释了超过 100% 的定价方差，因为重叠部分被算了两次。若在特征尺子下先把 B 中与 A 重叠的部分剔除，B 只得到 A 尚未解释的那一份，合计回到 100%。美国数据中，部分特征两两相关高达 0.94（论文表 5）。


图 1：两个相关特征下的两把尺子。示意性示例（虚构数字，并非论文估计值）。


palette = ({
  naipca_iab: "#18557f", complete: "#18557f",
  qz_ipca: "#8a6a1a",
  ipca: "#6f9cc0", rp_pca: "#7a7a7a", ff5: "#b3b3b3",
  naipca_beta_only: "#8a8378", beta_only: "#8a8378",
  band: "rgba(0,0,0,0.06)", muted: "rgba(0,0,0,0.6)", rule: "rgba(0,0,0,0.1)"
})
LANG = (document.documentElement.lang || "en").startsWith("zh") ? "zh" : "en"
STR = ({ en: { view: "View", cost: "Cost (bp per traded dollar)", universe: "Universe", sample: "Sample (months)", log: "Log scale", models: "Models", statistic: "Statistic", theme: "Theme", sort: "Sort by", method: "Method", scenario: "Scenario", block: "Block (months)", metric: "Metric", intervals: "Intervals", cost_bp: "One-way cost (bp)", failed: "Interactive data failed to load. The static figure is shown instead." },
        zh: { view: "视图", cost: "成本（每交易一美元，基点）", universe: "股票池", sample: "样本（月）", log: "对数坐标", models: "模型", statistic: "统计量", theme: "主题", sort: "排序", method: "方法", scenario: "情景", block: "块长（月）", metric: "指标", intervals: "区间", cost_bp: "单边成本（基点）", failed: "交互数据加载失败，改为显示静态图。" } })
t = (k) =&gt; STR[LANG][k] ?? STR.en[k] ?? k
fmt2 = (x) =&gt; (x == null || Number.isNaN(x)) ? "n/a" : x.toFixed(2)
fmt1 = (x) =&gt; (x == null || Number.isNaN(x)) ? "n/a" : x.toFixed(1)
fmtBp = (x) =&gt; (x == null || Number.isNaN(x)) ? "&gt; 500" : `${Math.round(x)} bp`
parseMonth = (s) =&gt; new Date(`${s}-01T00:00:00Z`)
// Sharpe, annualised, sample std (ddof = 1): matches the release convention
sharpe = (r) =&gt; {
  const n = r.length, m = r.reduce((a, b) =&gt; a + b, 0) / n
  const v = r.reduce((a, b) =&gt; a + (b - m) ** 2, 0) / (n - 1)
  const vol = Math.sqrt(v) * Math.sqrt(12)
  return vol &gt; 1e-12 ? (m * 12) / vol : NaN
}
netSeries = (r, to, bp) =&gt; r.map((x, i) =&gt; x - to[i] * bp / 1e4)
wealthPath = (r) =&gt; { let w = 1; return r.map((x) =&gt; (w *= 1 + x)) }
nberMarks = (nber) =&gt; Plot.rectX(nber, { x1: (d) =&gt; parseMonth(d.start), x2: (d) =&gt; parseMonth(d.end), fill: palette.band })






















































































viewof gf_toy_rho = Inputs.range([0, 0.95], { step: 0.05, value: 0.8, label: LANG === "zh" ? "相关系数 ρ" : "Correlation ρ" })







gf_toy_calc = {
  const r = gf_toy_rho
  return {
    r,
    shareA: (1 + r) / 2,
    shareB: (1 + r) / 2,
    shareBnet: (1 - r) / 2,
    angleQ: Math.acos(r) * 180 / Math.PI,
    g: [1 / Math.sqrt(2 * (1 + r)), 1 / Math.sqrt(2 * (1 + r))]
  }
}
gf_toy_curve = (q) =&gt; Array.from({ length: 181 }, (_, i) =&gt; {
  const th = (i * 2) * Math.PI / 180, c = Math.cos(th), s = Math.sin(th)
  const k = 1 / Math.sqrt(q(c, s))
  return { x: c * k, y: s * k }
})
gf_toy_circle = gf_toy_curve((c, s) =&gt; c * c + s * s)
gf_toy_ellipse = gf_toy_curve((c, s) =&gt; c * c + s * s + 2 * gf_toy_rho * c * s)
gf_toy_L = LANG === "zh"
  ? { wa: "特征 A 的系数", wb: "特征 B 的系数", g: "定价方向", plain: "普通尺子（单位矩阵）", data: "数据之尺（特征度量）",
      blockA: "含 A 的因子块", blockB: "含 B 的因子块", blockBnet: "B（剔除与 A 的重叠）", share: "被解释的定价方差占比", sep: "分块后合计" }
  : { wa: "Weight on characteristic A", wb: "Weight on characteristic B", g: "priced", plain: "Plain ruler (identity)", data: "Data ruler (characteristic metric)",
      blockA: "Block holding A", blockB: "Block holding B", blockBnet: "B net of A", share: "Share of priced variance explained", sep: "total" }





































gf_toy_geometry = () =&gt; Plot.plot({
  width: 300, height: 300, marginLeft: 44, marginBottom: 40,
  style: { fontFamily: "inherit", fontSize: 12 },
  ariaLabel: "Figure 1, left panel: coefficient plane",
  ariaDescription: `Unit circle of the plain ruler and unit ellipse of the data ruler for correlation ${gf_toy_rho.toFixed(2)}, with the coefficient vectors of A and B and the priced direction.`,
  x: { domain: [-2.2, 2.2], label: gf_toy_L.wa, ticks: 5 },
  y: { domain: [-2.2, 2.2], label: gf_toy_L.wb, ticks: 5 },
  clip: true,
  marks: [
    Plot.ruleX([0], { stroke: palette.rule }),
    Plot.ruleY([0], { stroke: palette.rule }),
    Plot.line(gf_toy_circle, { x: "x", y: "y", stroke: palette.muted, strokeDasharray: "4 3" }),
    Plot.line(gf_toy_ellipse, { x: "x", y: "y", stroke: palette.naipca_iab, strokeWidth: 1.8 }),
    Plot.arrow([{ x1: 0, y1: 0, x2: 1, y2: 0 }, { x1: 0, y1: 0, x2: 0, y2: 1 }], { x1: "x1", y1: "y1", x2: "x2", y2: "y2", stroke: palette.qz_ipca, strokeWidth: 2, headLength: 8 }),
    Plot.arrow([{ x1: 0, y1: 0, x2: gf_toy_calc.g[0], y2: gf_toy_calc.g[1] }], { x1: "x1", y1: "y1", x2: "x2", y2: "y2", stroke: "#222", strokeWidth: 2, headLength: 8 }),
    Plot.text([{ x: 1.18, y: 0.16, t: "a" }, { x: 0.16, y: 1.2, t: "b" }], { x: "x", y: "y", text: "t", fill: palette.qz_ipca, fontWeight: 600 }),
    Plot.text([{ x: gf_toy_calc.g[0] + 0.12, y: gf_toy_calc.g[1] + 0.12, t: gf_toy_L.g }], { x: "x", y: "y", text: "t", fill: "#222", textAnchor: "start" })
  ]
})







gf_toy_rows = [
  { ruler: gf_toy_L.plain, block: gf_toy_L.blockA, share: gf_toy_calc.shareA },
  { ruler: gf_toy_L.plain, block: gf_toy_L.blockB, share: gf_toy_calc.shareB },
  { ruler: gf_toy_L.data, block: gf_toy_L.blockA, share: gf_toy_calc.shareA },
  { ruler: gf_toy_L.data, block: gf_toy_L.blockBnet, share: gf_toy_calc.shareBnet }
]
gf_toy_bars = () =&gt; Plot.plot({
  width: Math.min(420, Math.max(280, width - 340)), height: 220, marginLeft: 12, marginRight: 40, marginTop: 28, marginBottom: 48,
  style: { fontFamily: "inherit", fontSize: 12 },
  ariaLabel: "Figure 1, right panel: explained shares by ruler",
  ariaDescription: `Plain ruler: the two blocks together explain ${Math.round((1 + gf_toy_rho) * 100)} percent of the priced variance. Data ruler: they explain 100 percent.`,
  x: { domain: [0, 2], label: gf_toy_L.share, labelAnchor: "center", labelOffset: 36, tickFormat: (d) =&gt; `${Math.round(d * 100)}%`, ticks: 5 },
  y: { label: null, axis: null, domain: [gf_toy_L.plain, gf_toy_L.data], padding: 0.55 },
  color: { domain: [gf_toy_L.blockA, gf_toy_L.blockB, gf_toy_L.blockBnet], range: [palette.naipca_iab, palette.ipca, palette.qz_ipca], legend: true },
  marks: [
    Plot.barX(gf_toy_rows, Plot.stackX({ y: "ruler", x: "share", fill: "block", insetLeft: 1, insetRight: 1 })),
    Plot.text([gf_toy_L.plain, gf_toy_L.data], { y: (d) =&gt; d, x: 0, text: (d) =&gt; d, dy: -20, textAnchor: "start", fill: "#222" }),
    Plot.ruleX([1], { stroke: "#222", strokeDasharray: "3 3" }),
    Plot.text(gf_toy_rows.filter((_, i) =&gt; i % 2 === 1), { y: "ruler", x: (d) =&gt; gf_toy_calc.shareA + d.share, text: (d) =&gt; `${Math.round((gf_toy_calc.shareA + d.share) * 100)}%`, dx: 4, textAnchor: "start", fill: "#222", fontWeight: 600 })
  ]
})
















gf_toy_view = html`&lt;div style="display:flex;flex-wrap:wrap;gap:12px 24px;align-items:flex-start"&gt;
  &lt;div&gt;${gf_toy_geometry()}&lt;/div&gt;
  &lt;div style="flex:1 1 280px;min-width:0;max-width:440px"&gt;${gf_toy_bars()}
  &lt;p class="figcaption" style="margin-top:.4rem"&gt;${LANG === "zh"
    ? `A 与 B 的夹角：普通尺子下为 90°，数据之尺下为 ${gf_toy_calc.angleQ.toFixed(0)}°。两者的重叠 a′Qb = ${gf_toy_rho.toFixed(2)}。普通尺子下两个因子块合计声称解释 ${Math.round((1 + gf_toy_rho) * 100)}% 的定价方差；数据之尺下合计为 100%。`
    : `Angle between a and b: 90° under the plain ruler, ${gf_toy_calc.angleQ.toFixed(0)}° under the data ruler. Overlap a′Qb = ${gf_toy_rho.toFixed(2)}. Under the plain ruler the two blocks together claim ${Math.round((1 + gf_toy_rho) * 100)}% of the priced variance; under the data ruler they claim 100%.`}&lt;/p&gt;
  &lt;/div&gt;
&lt;/div&gt;`







读图说明。左图：A、B 的系数向量（金色）与被定价方向（深色）；虚线为普通尺子的单位圆，蓝线为特征尺子的单位椭圆 a^{\top} Q a = 1，其中 Q 的对角元为 1、非对角元为 ρ。右图：在 Q 度量下，各模块所能解释的被定价方向方差的比例。每个模块单独解释 (1+\rho)/2；剔除与 A 的重叠后，B 解释 (1-\rho)/2。来源：基于论文定义（第 2 节；图 3，第 34 页）的示意计算，无数据文件。

5 一个简单例子

palette = ({
  naipca_iab: "#18557f", complete: "#18557f",
  qz_ipca: "#8a6a1a",
  ipca: "#6f9cc0", rp_pca: "#7a7a7a", ff5: "#b3b3b3",
